function androidbox_sm_get() {$d=ab_sm_defaults();$v=get_option(AB_SM_OPT,[]);foreach($d as $k=>$defaults)if(isset($v[$k])&&is_array($defaults))$d[$k]=wp_parse_args($v[$k],$defaults);return $d;}
function androidbox_sm_page_url($slug){$p=get_page_by_path($slug,OBJECT,'page');return $p?get_permalink($p):home_url('/'.trim($slug,'/').'/');}
function androidbox_sm_image_url($value){if(is_numeric($value)){$u=wp_get_attachment_image_url((int)$value,'full');return $u?:'';}return esc_url($value);}
function ab_sm_sanitize($in){$d=ab_sm_defaults();$o=$d;foreach(['site'=>['tagline','brand_tagline','support_text','footer_text','affiliate_note'],'hero'=>['title','text','button_text'],'coupons'=>['title'],'sidebar'=>['title']] as $s=>$keys)foreach($keys as $k)if(isset($in[$s][$k]))$o[$s][$k]=sanitize_text_field($in[$s][$k]);foreach(['site'=>['support_url'],'hero'=>['button_url'],'social'=>array_keys($d['social']),'coupons'=>['aliexpress_url','geekbuying_url']] as $s=>$keys)foreach($keys as $k)if(isset($in[$s][$k]))$o[$s][$k]=esc_url_raw($in[$s][$k]);$o['hero']['image']=sanitize_text_field($in['hero']['image']??'');$o['hero']['show_overlay']=!empty($in['hero']['show_overlay']);foreach($in['categories']??[] as $i=>$r)$o['categories'][$i]=['title'=>sanitize_text_field($r['title']??''),'description'=>sanitize_text_field($r['description']??''),'icon'=>sanitize_text_field($r['icon']??''),'url'=>esc_url_raw($r['url']??'')];foreach($in['sidebar']['articles']??[] as $i=>$r)$o['sidebar']['articles'][$i]=['title'=>sanitize_text_field($r['title']??''),'date'=>sanitize_text_field($r['date']??''),'url'=>esc_url_raw($r['url']??''),'image'=>sanitize_text_field($r['image']??'')];foreach($in['bottom']??[] as $i=>$r)$o['bottom'][$i]=['title'=>sanitize_text_field($r['title']??''),'text'=>sanitize_text_field($r['text']??''),'image'=>sanitize_text_field($r['image']??'')];foreach(['aliexpress_image','geekbuying_image'] as $k)if(isset($in['coupons'][$k]))$o['coupons'][$k]=sanitize_text_field($in['coupons'][$k]);return $o;}
add_action('admin_init',function(){register_setting('ab_sm_group',AB_SM_OPT,['type'=>'array','sanitize_callback'=>'ab_sm_sanitize','default'=>ab_sm_defaults()]);});
add_action('admin_menu',function(){add_menu_page('AndroidBox.cz','AndroidBox.cz','manage_options','androidbox-site-manager','ab_sm_page','dashicons-screenoptions',3);add_submenu_page('androidbox-site-manager','Nastavení webu','Nastavení webu','manage_options','androidbox-site-manager','ab_sm_page');add_submenu_page('androidbox-site-manager','Stránky a menu','Stránky a menu','manage_options','androidbox-site-structure','ab_sm_structure');});
add_action('admin_enqueue_scripts',function($hook){if(strpos($hook,'androidbox-site')===false)return;wp_enqueue_media();wp_enqueue_style('ab-sm-admin',plugins_url('admin.css',__FILE__),[],AB_SM_VER);wp_enqueue_script('ab-sm-admin',plugins_url('admin.js',__FILE__),['jquery'],AB_SM_VER,true);});
function ab_sm_input($name,$value,$type='text'){if($type==='textarea')printf('<textarea class="large-text" rows="4" name="%s">%s</textarea>',esc_attr($name),esc_textarea($value));else printf('<input class="regular-text" type="%s" name="%s" value="%s">',esc_attr($type),esc_attr($name),esc_attr($value));}
function ab_sm_media($name,$value){printf('<div class="ab-media-row"><input class="regular-text" type="text" name="%s" value="%s" data-ab-media-input><button class="button ab-media" type="button">Vybrat obrázek</button></div>',esc_attr($name),esc_attr($value));}
function ab_sm_label($label,$name,$value,$type='text'){echo '<label>'.esc_html($label).'</label>';ab_sm_input($name,$value,$type);}
function ab_sm_page(){if(!current_user_can('manage_options'))return;$o=androidbox_sm_get();$tab=sanitize_key($_GET['tab']??'homepage');$tabs=['homepage'=>'Homepage','categories'=>'Sekce','sidebar'=>'Sidebar','social'=>'Sítě','coupons'=>'Kupóny','bottom'=>'Spodní bloky','site'=>'Web'];echo '<div class="wrap androidbox-sm"><h1>AndroidBox.cz – Site Manager <span class="ab-version">4.2.0</span></h1><p>Kompletní ovládání obsahu webu z jednoho místa.</p><nav class="nav-tab-wrapper">';foreach($tabs as $key=>$label)printf('<a class="nav-tab %s" href="%s">%s</a>',$tab===$key?'nav-tab-active':'',esc_url(admin_url('admin.php?page=androidbox-site-manager&tab='.$key)),esc_html($label));echo '</nav><form method="post" action="options.php">';settings_fields('ab_sm_group');if($tab==='homepage'){echo '<div class="ab-card"><h2>Hero</h2><label>Obrázek</label>';ab_sm_media('androidbox_site_manager[hero][image]',$o['hero']['image']);ab_sm_label('Nadpis','androidbox_site_manager[hero][title]',$o['hero']['title']);ab_sm_label('Text','androidbox_site_manager[hero][text]',$o['hero']['text'],'textarea');ab_sm_label('Text tlačítka','androidbox_site_manager[hero][button_text]',$o['hero']['button_text']);ab_sm_label('URL tlačítka','androidbox_site_manager[hero][button_url]',$o['hero']['button_url'],'url');echo '<label><input type="checkbox" name="androidbox_site_manager[hero][show_overlay]" value="1" '.checked($o['hero']['show_overlay'],true,false).'> Zobrazit textovou vrstvu</label></div>';}elseif($tab==='categories'){echo '<div class="ab-card"><h2>6 hlavních sekcí</h2>';foreach($o['categories'] as $i=>$r){echo '<div class="ab-repeater"><h3>'.esc_html(($i+1).'. '.$r['title']).'</h3>';ab_sm_label('Název',"androidbox_site_manager[categories][$i][title]",$r['title']);ab_sm_label('Popis',"androidbox_site_manager[categories][$i][description]",$r['description']);ab_sm_label('Ikona',"androidbox_site_manager[categories][$i][icon]",$r['icon']);ab_sm_label('URL',"androidbox_site_manager[categories][$i][url]",$r['url'],'url');echo '</div>';}echo '</div>';}elseif($tab==='sidebar'){echo '<div class="ab-card"><h2>Sidebar</h2>';ab_sm_label('Nadpis','androidbox_site_manager[sidebar][title]',$o['sidebar']['title']);foreach($o['sidebar']['articles'] as $i=>$r){echo '<div class="ab-repeater"><h3>Článek '.($i+1).'</h3>';ab_sm_label('Název',"androidbox_site_manager[sidebar][articles][$i][title]",$r['title']);ab_sm_label('Datum',"androidbox_site_manager[sidebar][articles][$i][date]",$r['date']);ab_sm_label('URL',"androidbox_site_manager[sidebar][articles][$i][url]",$r['url'],'url');echo '<label>Náhled</label>';ab_sm_media("androidbox_site_manager[sidebar][articles][$i][image]",$r['image']);echo '</div>';}echo '</div>';}elseif($tab==='social'){echo '<div class="ab-card"><h2>Sociální sítě</h2>';foreach(['youtube'=>'YouTube','facebook'=>'Facebook','telegram'=>'Telegram','instagram'=>'Instagram','rss'=>'RSS'] as $k=>$label)ab_sm_label($label.' URL',"androidbox_site_manager[social][$k]",$o['social'][$k],'url');echo '</div>';}elseif($tab==='coupons'){echo '<div class="ab-card"><h2>Kupóny a bannery</h2>';ab_sm_label('Nadpis','androidbox_site_manager[coupons][title]',$o['coupons']['title']);foreach(['aliexpress'=>'AliExpress','geekbuying'=>'Geekbuying'] as $k=>$label){echo '<div class="ab-repeater"><h3>'.esc_html($label).'</h3><label>Banner</label>';ab_sm_media("androidbox_site_manager[coupons][{$k}_image]",$o['coupons'][$k.'_image']);ab_sm_label('URL',"androidbox_site_manager[coupons][{$k}_url]",$o['coupons'][$k.'_url'],'url');echo '</div>';}echo '</div>';}elseif($tab==='bottom'){echo '<div class="ab-card"><h2>4 spodní bloky</h2>';foreach($o['bottom'] as $i=>$r){echo '<div class="ab-repeater"><h3>Blok '.($i+1).'</h3>';ab_sm_label('Nadpis',"androidbox_site_manager[bottom][$i][title]",$r['title']);ab_sm_label('Text',"androidbox_site_manager[bottom][$i][text]",$r['text']);echo '<label>Ikona</label>';ab_sm_media("androidbox_site_manager[bottom][$i][image]",$r['image']);echo '</div>';}echo '</div>';}else{echo '<div class="ab-card"><h2>Web</h2>';ab_sm_label('Horní proužek','androidbox_site_manager[site][tagline]',$o['site']['tagline']);ab_sm_label('Podtitul značky','androidbox_site_manager[site][brand_tagline]',$o['site']['brand_tagline']);ab_sm_label('Text podpory','androidbox_site_manager[site][support_text]',$o['site']['support_text']);ab_sm_label('URL podpory','androidbox_site_manager[site][support_url]',$o['site']['support_url'],'url');ab_sm_label('Footer','androidbox_site_manager[site][footer_text]',$o['site']['footer_text'],'textarea');ab_sm_label('Affiliate upozornění','androidbox_site_manager[site][affiliate_note]',$o['site']['affiliate_note'],'textarea');echo '</div>';}submit_button('Uložit změny');echo '</form></div>';}
function ab_sm_create_pages(){foreach(ab_sm_defaults()['pages'] as $slug=>$data)if(!get_page_by_path($slug,OBJECT,'page'))wp_insert_post(['post_title'=>$data['title'],'post_name'=>$slug,'post_content'=>'<p>'.esc_html($data['content']).'</p>','post_status'=>'publish','post_type'=>'page']);}
function ab_sm_create_menu(){ab_sm_create_pages();$name='AndroidBox.cz – hlavní menu';$menu=wp_get_nav_menu_object($name);$id=$menu?(int)$menu->term_id:wp_create_nav_menu($name);if(is_wp_error($id))return;$existing=[];foreach((array)wp_get_nav_menu_items($id) as $item)$existing[(int)$item->object_id]=1;foreach(['android-tv-boxy'=>'Android TV boxy','kodi-coreelec'=>'Kodi & CoreELEC','navody'=>'Návody','hardware'=>'Hardware','kupony'=>'Kupóny','komunita'=>'Komunita'] as $slug=>$title){$p=get_page_by_path($slug);if($p&&!isset($existing[$p->ID]))wp_update_nav_menu_item($id,0,['menu-item-title'=>$title,'menu-item-object'=>'page','menu-item-object-id'=>$p->ID,'menu-item-type'=>'post_type','menu-item-status'=>'publish']);}$loc=get_theme_mod('nav_menu_locations',[]);$loc['primary']=$id;set_theme_mod('nav_menu_locations',$loc);}
function ab_sm_structure(){if(!current_user_can('manage_options'))return;if(isset($_POST['ab_action'])&&check_admin_referer('ab_structure')){if($_POST['ab_action']==='pages')ab_sm_create_pages();if($_POST['ab_action']==='menu')ab_sm_create_menu();if($_POST['ab_action']==='front'){ab_sm_create_pages();$p=get_page_by_path('android-tv-boxy');if($p){update_option('show_on_front','page');update_option('page_on_front',$p->ID);}}}echo '<div class="wrap androidbox-sm"><h1>AndroidBox.cz – Stránky a menu</h1><div class="ab-card"><h2>Automatická struktura</h2><form method="post">'.wp_nonce_field('ab_structure','_wpnonce',true,false).'<button class="button button-primary" name="ab_action" value="pages">Vytvořit / opravit stránky</button> <button class="button button-primary" name="ab_action" value="menu">Vytvořit / opravit menu</button> <button class="button" name="ab_action" value="front">Nastavit homepage</button></form></div><div class="ab-card"><h2>Stránky</h2><table class="widefat striped"><tr><th>Název</th><th>Slug</th><th>Stav</th></tr>';foreach(ab_sm_defaults()['pages'] as $slug=>$data){$p=get_page_by_path($slug,OBJECT,'page');echo '<tr><td>'.esc_html($data['title']).'</td><td><code>'.esc_html($slug).'</code></td><td>'.($p?'Vytvořena':'Chybí').'</td></tr>';}echo '</table></div></div>';}
register_activation_hook(__FILE__,function(){ab_sm_create_pages();ab_sm_create_menu();});
